window.BANKS={"problems":[{"id":"ch1-convert-01","topic":"ch1-number-systems","type":"numeric","prompt":"Convert decimal 45 to binary and hexadecimal. Enter both values.","fields":["Binary","Hexadecimal"],"answers":["101101","2D"],"steps":["Repeated division or place values give 32+8+4+1.","45 decimal is 2D hexadecimal."],"source":"Chapter 1 number representation material","exerciseType":"base-conversion"},{"id":"ch1-twos-01","topic":"ch1-number-systems","type":"numeric","prompt":"Represent Ã¢Ë†â€™19 using 8-bit two\u0027s complement. Enter the 8-bit binary representation.","fields":["8-bit binary"],"answers":["11101101"],"steps":["Write +19 as 00010011.","Invert and add one to obtain 11101101."],"source":"Chapter 1 two\u0027s-complement objectives","exerciseType":"twos-complement"},{"id":"ch1-noise-01","topic":"ch1-logic-levels","type":"numeric","prompt":"A logic family guarantees VOH(min)=2.7 V and VIH(min)=2.0 V. What is the high-level noise margin?","fields":["High noise margin (V)"],"answers":["0.7"],"steps":["NMH=VOH(min)Ã¢Ë†â€™VIH(min).","2.7Ã¢Ë†â€™2.0=0.7 V."],"source":"Chapter 1 logic levels and noise margins","exerciseType":"noise-margin"},{"id":"ch2-boolean-canonical-01","topic":"ch2-boolean","type":"numeric","prompt":"For F(A,B)=1 on minterms m1 and m2 only, write canonical SOP using A and B (apostrophe means NOT).","fields":["SOP"],"answers":["A\u0027B+AB\u0027"],"steps":["m1 is A\u0027B.","m2 is AB\u0027.","OR the minterms."],"source":"Chapter 2 Boolean algebra objectives","exerciseType":"canonical-sop"},{"id":"ch2-delay-01","topic":"ch2-mux","type":"numeric","prompt":"A 4-to-1 MUX has two cascaded 25 ps logic levels. What is the worst-case delay?","fields":["Delay (ps)"],"answers":["50"],"steps":["Two serial levels each contribute 25 ps.","Total path delay is 2Ãƒâ€”25 ps."],"source":"Chapter 2 gate-delay lecture material","exerciseType":"gate-delay"},{"id":"ch2-kmap-solve-01","topic":"ch2-kmap","type":"kmap","prompt":"For F(A,B,C)=ÃŽÂ£m(1,3,5,7), give a minimum SOP expression using apostrophe for complement and + for OR.","fields":["Minimum SOP"],"answers":["C"],"steps":["The listed minterms are 001, 011, 101, and 111.","All have C=1 while A and B vary, so the four-cell group reduces to C."],"source":"Chapter 2 Karnaugh-map objectives","variables":["A","B","C"],"minterms":[1,3,5,7],"dontcares":[],"exerciseType":"sop-kmap"},{"id":"ch2-kmap-4var-01","topic":"ch2-kmap","type":"kmap","variables":["A","B","C","D"],"minterms":[1,3,4,6,9,11,12,14],"dontcares":[],"prompt":"Use a 4-variable K-map to find a minimum SOP for F(A,B,C,D)=ÃŽÂ£m(1,3,4,6,9,11,12,14).","fields":["Minimum SOP"],"answers":["B\u0027D+BD\u0027"],"steps":["Group minterms {1,3,9,11}; B=0 and D=1 stay fixed, yielding B\u0027D.","Group minterms {4,6,12,14}; B=1 and D=0 stay fixed, yielding BD\u0027.","The minimum SOP is B\u0027D+BD\u0027."],"source":"4341studyguide.pdf pp. 9Ã¢â‚¬â€œ10; the verified CS 4341 sample exam uses this same minterm set.","exerciseType":"sop-kmap"},{"id":"ch3-timing-problem-01","topic":"ch3-timing","type":"numeric","prompt":"A register-to-register path has tCQ=35 ps, combinational delay=210 ps, setup=25 ps, and zero skew. What minimum clock period does this path require?","fields":["Minimum period (ps)"],"answers":["270"],"steps":["Add clock-to-Q, combinational, and setup delays.","35+210+25=270 ps."],"source":"Chapter 3 sequential timing objectives","exerciseType":"sequential-timing"},{"id":"ch3-parallel-01","topic":"ch3-timing","type":"numeric","prompt":"Four independent 32-bit additions are implemented with four parallel adders. How many adder cycles are required, assuming each adder completes in one cycle?","fields":["Cycles"],"answers":["1"],"steps":["Independent operations execute concurrently.","The cycle count is one, subject to the adder\u0027s critical path."],"source":"Chapter 3 parallelism material","exerciseType":"parallelism"},{"id":"ch3-fsm-problem-01","topic":"ch3-fsm","type":"numeric","prompt":"A two-state Moore machine has state S0 output 0 and state S1 output 1. What output is produced while the machine is in S1?","fields":["Output"],"answers":["1"],"steps":["A Moore output is determined by the current state.","The stated output for S1 is 1."],"source":"Chapter 3 finite-state-machine objectives","exerciseType":"fsm-output"},{"id":"ch4-truth-table-01","topic":"ch4-combinational-hdl","type":"numeric","prompt":"Implement the combinational function Y=A XOR B. Enter Y for inputs AB=00, 01, 10, 11 in that order.","fields":["Output sequence"],"answers":["0110"],"steps":["XOR is 1 exactly when the inputs differ.","Rows 00,01,10,11 give 0,1,1,0."],"source":"Chapter 4 learning objectives; Chapter 2 logic definitions","exerciseType":"combinational-hdl"},{"id":"ch4-state-01","topic":"ch4-sequential-hdl","type":"numeric","prompt":"A positive-edge-triggered D flip-flop has Q=0. At a rising edge D=1; at the next rising edge D=0. Give Q after the second rising edge.","fields":["Q"],"answers":["0"],"steps":["The first rising edge captures 1.","The second rising edge captures 0."],"source":"Chapter 4 sequential HDL objectives","exerciseType":"sequential-hdl"},{"id":"ch5-add-01","topic":"ch5-alu","type":"numeric","prompt":"Add the 8-bit unsigned values 01101101 and 00110111. Give the 8-bit sum and indicate carry-out.","fields":["Sum bits","Carry-out (0/1)"],"answers":["10100100","0"],"steps":["Convert or add bitwise: 109+55=164.","164 is 10100100; it is less than 256, so carry-out is zero."],"source":"Chapter 5 adder and ALU objectives","exerciseType":"alu-arithmetic"},{"id":"ch5-float-problem-01","topic":"ch5-float","type":"numeric","prompt":"Encode +1.5 in IEEE 754 single precision. Enter the 32-bit hex word.","fields":["Hex word"],"answers":["3FC00000"],"steps":["1.5 = 1.1Ã¢â€šâ€š Ãƒâ€” 2Ã¢ÂÂ°.","Sign=0, biased exponent=127 (0x7F), fraction begins 100Ã¢â‚¬Â¦","Concatenate fields: 0x3FC00000."],"source":"Chapter 5 floating-point objectives","exerciseType":"ieee-754"},{"id":"ch5-array-depth-01","topic":"ch5-arrays","type":"numeric","prompt":"A memory has 256 words with 16 bits per word. How many address bits select a word?","fields":["Address bits"],"answers":["8"],"steps":["256=2^8 distinct words.","Eight address bits select one word."],"source":"Chapter 5 memory-array objectives","exerciseType":"memory-capacity"},{"id":"ch6-encode-01","topic":"ch6-encoding","type":"numeric","prompt":"Encode add $t0,$t1,$t2 as a 32-bit MIPS R-type instruction. Enter hexadecimal.","fields":["Instruction word"],"answers":["012A4020"],"steps":["add has opcode 0, funct 0x20, shamt 0.","rs=$t1=9, rt=$t2=10, rd=$t0=8.","Fields yield 0x012A4020."],"source":"Chapter 6 instruction encoding objectives","exerciseType":"instruction-encoding"},{"id":"ch6-array-01","topic":"ch6-arrays","type":"numeric","prompt":"An integer array begins at byte address 1000. What byte address contains element A[7], with 4-byte elements and zero-based indexing?","fields":["Byte address"],"answers":["1028"],"steps":["Offset=7Ãƒâ€”4=28 bytes.","1000+28=1028."],"source":"Chapter 6 arrays and index arithmetic objectives","exerciseType":"array-addressing"},{"id":"ch6-branch-02","topic":"ch6-encoding","type":"numeric","prompt":"A beq is at address 0x00400020 and its target is 0x00400050. What signed 16-bit branch immediate is encoded?","fields":["Immediate decimal"],"answers":["11"],"steps":["Branch base is PC+4=0x00400024.","Difference to target is 0x2C=44 bytes.","Word offset is 44/4=11."],"source":"Chapter 6 branch addressing objectives","exerciseType":"instruction-encoding"},{"id":"ch6-stack-01","topic":"ch6-functions","type":"numeric","prompt":"The stack pointer is 0x7FFFEFFC. A function allocates 16 bytes by moving the stack pointer downward. What is the new stack pointer?","fields":["Address (hex)"],"answers":["7FFFEFEC"],"steps":["Subtract 0x10 bytes from the stack pointer.","0x7FFFEFFCÃ¢Ë†â€™0x10=0x7FFFEFEC."],"source":"Chapter 6 function and stack objectives","exerciseType":"stack-frames"},{"id":"ch6-loop-01","topic":"ch6-control","type":"numeric","prompt":"A loop begins with i=0 and increments i once per iteration while i\u003c5. How many iterations execute?","fields":["Iterations"],"answers":["5"],"steps":["The body executes at i values 0,1,2,3,4.","It stops when i becomes 5."],"source":"Chapter 6 C loops in MIPS objectives","exerciseType":"mips-control-flow"},{"id":"ch7-cpu-time-01","topic":"ch7-performance","type":"numeric","prompt":"A program executes 2 million instructions at average CPI 1.5 on a 2 GHz processor. Compute CPU time in milliseconds.","fields":["Time (ms)"],"answers":["1.5"],"steps":["CPU time = 2,000,000Ãƒâ€”1.5Ãƒâ€”(1/2,000,000,000) seconds.","That equals 0.0015 seconds = 1.5 ms."],"source":"Chapter 7 performance objectives","exerciseType":"cpu-performance"},{"id":"ch7-pipeline-problem-01","topic":"ch7-pipeline","type":"numeric","prompt":"Under an ideal five-stage pipeline with no stalls, how many cycles are required for 12 instructions?","fields":["Cycles"],"answers":["16"],"steps":["Ideal cycles = n+4.","12+4=16."],"source":"Chapter 7 pipelining objectives","exerciseType":"pipeline-timing"},{"id":"ch8-amat-01","topic":"ch8-cache","type":"numeric","prompt":"A cache has 1 ns hit time, 8% miss rate, and 40 ns miss penalty. Compute AMAT in ns.","fields":["AMAT (ns)"],"answers":["4.2"],"steps":["AMAT=hit time+miss rateÃƒâ€”miss penalty.","1+0.08Ãƒâ€”40=4.2 ns."],"source":"Chapter 8 cache performance objectives","exerciseType":"cache-performance"},{"id":"ch8-address-01","topic":"ch8-virtual-memory","type":"numeric","prompt":"A byte-addressed system uses 4 KiB pages. For virtual address 0x12345, give the page offset in hex and the virtual page number in hex.","fields":["Offset","VPN"],"answers":["345","12"],"steps":["4 KiB=2^12, so the low 12 bits are the page offset.","Offset=0x345; remaining high bits give VPN=0x12."],"source":"Chapter 8 memory translation objectives","exerciseType":"address-translation"},{"id":"ch8-io-address-01","topic":"ch8-io","type":"numeric","prompt":"A memory-mapped device register is assigned byte address 0xFFFF0008. What address is used by a byte-addressed load to access that register?","fields":["Address (hex)"],"answers":["FFFF0008"],"steps":["Memory-mapped I/O uses the device register\u0027s assigned address in the ordinary address space.","The byte address remains 0xFFFF0008."],"source":"Chapter 8 I/O objectives","exerciseType":"memory-mapped-io"}],"questions":[{"id":"ch1-number-systems-01","topic":"ch1-number-systems","type":"mcq","prompt":"In an 8-bit two\u0027s-complement representation, what is the range of representable integers?","choices":["âˆ’128 through 127","âˆ’127 through 128","0 through 255","âˆ’255 through 255"],"answer":0,"explanation":"An n-bit two\u0027s-complement value ranges from âˆ’2^(nâˆ’1) through 2^(nâˆ’1)âˆ’1."},{"id":"ch1-number-systems-02","topic":"ch1-number-systems","type":"tf","prompt":"In fixed-width two\u0027s-complement arithmetic, the most significant bit has a negative weight.","choices":["True","False"],"answer":0,"explanation":"The sign bit has weight âˆ’2^(nâˆ’1); remaining bits have positive powers-of-two weights."},{"id":"ch1-logic-levels-01","topic":"ch1-logic-levels","type":"mcq","prompt":"A noise margin measures which quantity?","choices":["The allowable gap between guaranteed output and input logic levels","The propagation delay of a gate","The maximum fan-out of a register","The number of voltage levels in a binary signal"],"answer":0,"explanation":"Noise margins quantify how much noise a signal can tolerate while remaining in a guaranteed logic range."},{"id":"ch1-logic-levels-02","topic":"ch1-logic-levels","type":"tf","prompt":"A digital input voltage between its specified VIL(max) and VIH(min) is guaranteed to be read as either 0 or 1.","choices":["True","False"],"answer":1,"explanation":"That interval is undefined; the receiver does not guarantee either logic value."},{"id":"ch2-sop-01","topic":"ch2-boolean","type":"mcq","prompt":"Canonical SOP includes a minterm for each truth-table row whereâ€¦","choices":["F=0","F=1","all inputs are 1","the row is a don\u0027t-care"],"answer":1,"explanation":"SOP is the OR of minterms for output-one rows."},{"id":"ch2-sop-02","topic":"ch2-boolean","type":"tf","prompt":"A canonical POS is formed from the rows where F=0.","choices":["True","False"],"answer":0,"explanation":"Each zero row contributes a maxterm to canonical POS."},{"id":"ch2-kmap-01","topic":"ch2-kmap","type":"mcq","prompt":"Why are adjacent K-map labels arranged in Gray-code order?","choices":["Adjacent cells differ in exactly one variable","The labels sort alphabetically","It makes every cell adjacent to every other cell","It removes don\u0027t-care conditions"],"answer":0,"explanation":"Gray ordering ensures geometric neighbors differ in one input literal."},{"id":"ch2-kmap-02","topic":"ch2-kmap","type":"tf","prompt":"The left and right edges of a conventional K-map are adjacent.","choices":["True","False"],"answer":0,"explanation":"K-map adjacency wraps around each dimension."},{"id":"ch2-mux-01","topic":"ch2-mux","type":"mcq","prompt":"How many select bits are needed for a 4-to-1 multiplexer?","choices":["1","2","3","4"],"answer":1,"explanation":"Two select bits encode four input choices."},{"id":"ch3-ff-01","topic":"ch3-storage","type":"mcq","prompt":"What distinguishes an edge-triggered flip-flop from a level-sensitive latch?","choices":["It samples on a clock edge","It has no state","It is combinational","It stores multiple words"],"answer":0,"explanation":"A flip-flop updates at an active clock edge; a latch is transparent during an enabled level."},{"id":"ch3-ff-02","topic":"ch3-storage","type":"tf","prompt":"A register is commonly built from multiple flip-flops sharing a clock.","choices":["True","False"],"answer":0,"explanation":"Each flip-flop stores one bit; a collection stores a multi-bit word."},{"id":"ch3-fsm-01","topic":"ch3-fsm","type":"mcq","prompt":"In a Moore FSM, the output is a function ofâ€¦","choices":["current state only","current inputs only","current state and current inputs","the next clock period"],"answer":0,"explanation":"Moore outputs depend on state; Mealy outputs depend on state and inputs."},{"id":"ch3-timing-01","topic":"ch3-timing","type":"tf","prompt":"Setup time is the required stability interval before the active clock edge.","choices":["True","False"],"answer":0,"explanation":"Hold time is the required stability interval after the edge."},{"id":"ch4-comb-01","topic":"ch4-combinational-hdl","type":"mcq","prompt":"A combinational HDL process should assign its output for every possible control path primarily toâ€¦","choices":["avoid inferring unintended storage","increase clock frequency","create a new state register","force a tri-state bus"],"answer":0,"explanation":"An incomplete combinational assignment can infer a latch that holds the prior value."},{"id":"ch4-comb-02","topic":"ch4-combinational-hdl","type":"tf","prompt":"A purely combinational circuit\u0027s outputs depend on its current inputs, not stored prior state.","choices":["True","False"],"answer":0,"explanation":"Combinational logic has no state element; sequential logic has stored state."},{"id":"ch4-seq-01","topic":"ch4-sequential-hdl","type":"mcq","prompt":"An edge-triggered HDL process is used to describe which hardware behavior?","choices":["Clocked state updates","An asynchronous combinational decoder only","A constant wire","A truth-table comment"],"answer":0,"explanation":"A clock-edge process describes sequential state updates, subject to the language\u0027s assignment semantics."},{"id":"ch4-seq-02","topic":"ch4-sequential-hdl","type":"tf","prompt":"A nonblocking assignment in a clocked process schedules a state update rather than immediately changing the value for subsequent statements in that process.","choices":["True","False"],"answer":0,"explanation":"Nonblocking assignments model simultaneous register updates in clocked logic in common Verilog teaching conventions."},{"id":"ch5-alu-01","topic":"ch5-alu","type":"mcq","prompt":"A carry-lookahead adder improves speed primarily byâ€¦","choices":["computing carries in parallel from generate/propagate signals","reducing operand width","removing the sum logic","using a slower clock"],"answer":0,"explanation":"Lookahead logic avoids waiting for a carry to ripple through every bit."},{"id":"ch5-alu-02","topic":"ch5-alu","type":"tf","prompt":"For fixed-point addition, operands should use compatible binary-point positions.","choices":["True","False"],"answer":0,"explanation":"Matching scales are needed for direct addition."},{"id":"ch5-float-01","topic":"ch5-float","type":"mcq","prompt":"In normalized IEEE 754 single precision, what is stored in the fraction field?","choices":["The sign bit","The exponent bias","The fraction after the implicit leading 1","The full significand including its leading 1"],"answer":2,"explanation":"For normalized values the leading significand bit is implicit; the fraction field stores the remaining bits."},{"id":"ch5-arrays-01","topic":"ch5-arrays","type":"tf","prompt":"A memory array with 2^k words requires k address bits to select a word.","choices":["True","False"],"answer":0,"explanation":"k binary address bits select one of 2^k locations."},{"id":"ch6-reg-01","topic":"ch6-mips","type":"mcq","prompt":"In the standard MIPS register convention, which register holds a function return address?","choices":["$sp","$ra","$v0","$a0"],"answer":1,"explanation":"$ra ($31) holds the return address for a call such as jal."},{"id":"ch6-load-01","topic":"ch6-mips","type":"tf","prompt":"The displacement in lw $t0, 12($sp) is a byte offset from the base register.","choices":["True","False"],"answer":0,"explanation":"The effective byte address is base + sign-extended displacement."},{"id":"ch6-encoding-01","topic":"ch6-encoding","type":"mcq","prompt":"Which field is present in an R-type instruction but absent from an I-type instruction?","choices":["opcode","rs","rt","shamt"],"answer":3,"explanation":"R-type format includes rd, shamt, and funct; I-type instead has a 16-bit immediate."},{"id":"ch6-endian-01","topic":"ch6-endian","type":"tf","prompt":"Little-endian stores the least significant byte at the lowest byte address.","choices":["True","False"],"answer":0,"explanation":"Endian order describes how a multi-byte value\u0027s bytes map to increasing addresses."},{"id":"ch6-branch-01","topic":"ch6-mips","type":"mcq","prompt":"For a taken classic MIPS PC-relative branch, the target isâ€¦","choices":["PC+4+(sign-extended immediate\u003c\u003c2)","PC+immediate","the 26-bit index concatenated with PC","the contents of $ra"],"answer":0,"explanation":"The branch displacement is word-scaled and relative to PC+4."},{"id":"ch6-shift-01","topic":"ch6-logic","type":"mcq","prompt":"For a logical left shift of an unsigned bit vector, which bits enter from the right?","choices":["Zeros","Copies of the sign bit","The shifted-out bits in reverse","The branch target"],"answer":0,"explanation":"A logical shift fills vacated positions with zeros."},{"id":"ch6-control-01","topic":"ch6-control","type":"tf","prompt":"A while loop can be translated by branching back to its test after the loop body.","choices":["True","False"],"answer":0,"explanation":"The loop test controls whether execution repeats or exits."},{"id":"ch6-functions-01","topic":"ch6-functions","type":"mcq","prompt":"Why does a non-leaf function commonly save $ra before making another call?","choices":["The nested jal overwrites $ra","$ra is the stack pointer","The callee always zeroes $ra","Branch immediates use $ra"],"answer":0,"explanation":"jal writes a new return address into $ra, so a function that needs its caller\u0027s return address must preserve it."},{"id":"ch6-addressing-01","topic":"ch6-addressing","type":"tf","prompt":"The stored-program concept places both instructions and data in addressable memory.","choices":["True","False"],"answer":0,"explanation":"A stored-program machine represents instructions as values in memory."},{"id":"ch6-array-index-01","topic":"ch6-arrays","type":"mcq","prompt":"For a zero-based array of 4-byte words, the byte offset of A[i] from the base isâ€¦","choices":["i","2i","4i","4+i"],"answer":2,"explanation":"Element index is scaled by the element size in bytes: address=base+4i."},{"id":"ch7-performance-01","topic":"ch7-performance","type":"mcq","prompt":"CPU execution time is computed asâ€¦","choices":["instruction count Ã— average CPI Ã— clock period","clock frequency Ã— CPI","instruction count / clock period","cache hit rate Ã— miss penalty"],"answer":0,"explanation":"CPU time = instruction count Ã— average CPI Ã— clock period."},{"id":"ch7-datapath-01","topic":"ch7-datapath","type":"tf","prompt":"For an R-type instruction in the basic single-cycle datapath, MemtoReg selects the ALU result for register writeback.","choices":["True","False"],"answer":0,"explanation":"MemtoReg chooses the writeback source; R-type uses the ALU result rather than loaded memory data."},{"id":"ch7-pipeline-01","topic":"ch7-pipeline","type":"mcq","prompt":"A RAW hazard occurs whenâ€¦","choices":["an instruction reads a register before an older instruction writes it","a branch changes the next PC","two instructions use separate registers","the clock period is too short"],"answer":0,"explanation":"Read-after-write is a data dependence hazard."},{"id":"ch7-pipeline-02","topic":"ch7-pipeline","type":"tf","prompt":"An ideal five-stage pipeline executing n instructions takes n+4 cycles, ignoring stalls and startup variations.","choices":["True","False"],"answer":0,"explanation":"The first instruction takes five stages and each following instruction adds one cycle."},{"id":"ch7-hazards-01","topic":"ch7-hazards","type":"mcq","prompt":"A branch creates a control hazard because it mayâ€¦","choices":["change which instruction is fetched next","write a register too early","change an ALU operand width","cause a cache block to shrink"],"answer":0,"explanation":"The correct next fetch address depends on the branch outcome/target."},{"id":"ch7-critical-01","topic":"ch7-critical-path","type":"tf","prompt":"The single-cycle clock period must accommodate the longest instruction path supported by that datapath.","choices":["True","False"],"answer":0,"explanation":"All instructions share one cycle, so the clock must cover the slowest path."},{"id":"ch7-multicycle-01","topic":"ch7-multicycle","type":"mcq","prompt":"In a multicycle CPU, different instruction classes may take different numbers of clock cycles becauseâ€¦","choices":["each instruction uses the stages it needs over multiple cycles","CPI is always one","memory is removed","the clock period changes every instruction"],"answer":0,"explanation":"Multicycle implementations reuse datapath resources across sequential cycles; instruction cycle counts vary."},{"id":"ch7-control-hazards-01","topic":"ch7-control-hazards","type":"tf","prompt":"A branch predictor can reduce control-hazard delay when it predicts the next fetch direction correctly.","choices":["True","False"],"answer":0,"explanation":"Correct prediction permits useful fetch while branch resolution is pending."},{"id":"ch7-control-match-01","topic":"ch7-datapath","type":"matching","prompt":"Match each single-cycle datapath control signal to its role.","pairs":[{"left":"RegWrite","right":"Enable register-file write"},{"left":"ALUSrc","right":"Select ALU second operand source"},{"left":"MemtoReg","right":"Select register writeback source"},{"left":"RegDst","right":"Select destination-register field"}],"explanation":"These control signals steer the standard single-cycle MIPS datapath."},{"id":"ch8-cache-01","topic":"ch8-cache","type":"mcq","prompt":"A direct-mapped cache with 64 lines needs how many index bits?","choices":["4","5","6","8"],"answer":2,"explanation":"Index bits = logâ‚‚(number of lines)=logâ‚‚64=6."},{"id":"ch8-cache-02","topic":"ch8-cache","type":"tf","prompt":"AMAT under a simple one-level model equals hit time plus miss rate times miss penalty.","choices":["True","False"],"answer":0,"explanation":"AMAT = hit time + miss rateÃ—miss penalty under this model."},{"id":"ch8-vm-01","topic":"ch8-virtual-memory","type":"mcq","prompt":"For a fixed page size, which virtual-address field is unchanged by address translation?","choices":["Page offset","Physical page number","TLB tag","Physical frame number"],"answer":0,"explanation":"The byte offset within a page is preserved; translation replaces the page number."},{"id":"ch8-io-01","topic":"ch8-io","type":"tf","prompt":"Memory-mapped I/O uses ordinary load/store address operations to access device registers.","choices":["True","False"],"answer":0,"explanation":"In memory-mapped I/O, device registers occupy part of the address space."},{"id":"ch1-number-systems-03","topic":"ch1-number-systems","type":"mcq","prompt":"Which 8-bit pattern represents âˆ’1 in two\u0027s complement?","choices":["10000001","11111111","00000001","10000000"],"answer":1,"explanation":"Negating +1 (00000001) by invert-plus-one gives 11111111."},{"id":"ch1-number-systems-04","topic":"ch1-number-systems","type":"mcq","prompt":"When adding two signed two\u0027s-complement numbers, which condition signals overflow?","choices":["The carry into the sign bit differs from carry out","The result has a leading 1","The operands have different signs","The low bit is 1"],"answer":0,"explanation":"Signed overflow occurs when the carry into and out of the sign position differ; equivalently, same-sign operands yield an opposite-sign result."},{"id":"ch1-number-systems-05","topic":"ch1-number-systems","type":"tf","prompt":"An n-bit two\u0027s-complement format has one more negative value than positive nonzero values.","choices":["True","False"],"answer":0,"explanation":"The range is âˆ’2^(nâˆ’1) through 2^(nâˆ’1)âˆ’1, so the most negative value has no positive counterpart."},{"id":"ch1-logic-levels-03","topic":"ch1-logic-levels","type":"mcq","prompt":"A driver has VOH(min)=2.7 V and the receiver has VIH(min)=2.0 V. What is the guaranteed high noise margin?","choices":["0.7 V","4.7 V","âˆ’0.7 V","2.0 V"],"answer":0,"explanation":"NMH=VOH(min)âˆ’VIH(min)=0.7 V."},{"id":"ch1-logic-levels-04","topic":"ch1-logic-levels","type":"mcq","prompt":"Which statement about XOR is correct?","choices":["It is 1 when an odd number of inputs are 1","It is 1 only when all inputs are 1","It is the complement of OR","It ignores all inputs except the first"],"answer":0,"explanation":"For two inputs XOR is 1 when they differ; generalized XOR is 1 for odd parity."},{"id":"ch1-logic-levels-05","topic":"ch1-logic-levels","type":"tf","prompt":"The interval between a receiver\u0027s VIL(max) and VIH(min) is a guaranteed third logic value.","choices":["True","False"],"answer":1,"explanation":"It is an undefined voltage region; the receiver does not guarantee either binary interpretation there."},{"id":"ch1-match-number","topic":"ch1-number-systems","type":"matching","prompt":"Match each representation concept to its defining property.","pairs":[{"left":"Unsigned n-bit range","right":"0 through 2^nâˆ’1"},{"left":"Two\u0027s-complement range","right":"âˆ’2^(nâˆ’1) through 2^(nâˆ’1)âˆ’1"},{"left":"Hex digit","right":"Four binary bits"},{"left":"Signed overflow","right":"Same-sign inputs produce opposite-sign result"}],"explanation":"The number interpretation depends on width and encoding; signed overflow is not simply carry-out."},{"id":"ch1-match-logic","topic":"ch1-logic-levels","type":"matching","prompt":"Match each voltage term to its role in a digital interface.","pairs":[{"left":"VOH(min)","right":"Driver\u0027s guaranteed high output"},{"left":"VIH(min)","right":"Receiver\u0027s guaranteed high input threshold"},{"left":"NMH","right":"VOH(min)âˆ’VIH(min)"},{"left":"Undefined input region","right":"Between guaranteed low and high input ranges"}],"explanation":"Noise margin combines driver output guarantees with receiver input requirements."},{"id":"ch2-boolean-02","topic":"ch2-boolean","type":"mcq","prompt":"Which identity is the absorption law?","choices":["A+AB=A","A+A\u0027=1","(AB)\u0027=A\u0027+B\u0027","AÂ·0=0"],"answer":0,"explanation":"A+AB factors to A(1+B)=A."},{"id":"ch2-boolean-03","topic":"ch2-boolean","type":"tf","prompt":"A canonical minterm contains every input variable exactly once, complemented or uncomplemented.","choices":["True","False"],"answer":0,"explanation":"A minterm is true for exactly one input combination because it includes all variables."},{"id":"ch2-boolean-04","topic":"ch2-boolean","type":"mcq","prompt":"By De Morgan\u0027s law, what is (A+B)\u0027?","choices":["A\u0027B\u0027","A\u0027+B\u0027","AB","A+B"],"answer":0,"explanation":"Complementing an OR gives the AND of the complemented terms."},{"id":"ch2-kmap-extra-01","topic":"ch2-kmap","type":"mcq","prompt":"A valid K-map group for SOP contains how many cells?","choices":["Any prime number","A power of two","Exactly one row","A multiple of three"],"answer":1,"explanation":"Groups have 1, 2, 4, 8, â€¦ cells and form rectangles under wraparound adjacency."},{"id":"ch2-kmap-extra-02","topic":"ch2-kmap","type":"tf","prompt":"A don\u0027t-care cell must be included in at least one K-map group.","choices":["True","False"],"answer":1,"explanation":"A don\u0027t-care may be used if it simplifies the function, or ignored."},{"id":"ch2-mux-02","topic":"ch2-mux","type":"mcq","prompt":"For a 2:1 MUX with S=0, which input is selected?","choices":["D0","D1","Both inputs are ORed","Neither input"],"answer":0,"explanation":"The select value zero routes D0 to the output."},{"id":"ch2-mux-03","topic":"ch2-mux","type":"tf","prompt":"A 3-to-8 decoder has three input bits and eight decoded output lines.","choices":["True","False"],"answer":0,"explanation":"An n-input decoder has 2^n outputs (subject to enable and output polarity)."},{"id":"ch2-match-boolean","topic":"ch2-boolean","type":"matching","prompt":"Match each canonical Boolean term with the row where it is true.","pairs":[{"left":"Minterm","right":"Exactly one input row"},{"left":"Canonical SOP","right":"OR of minterms for F=1 rows"},{"left":"Maxterm","right":"Exactly one zero row"},{"left":"Canonical POS","right":"AND of maxterms for F=0 rows"}],"explanation":"SOP is built from one-rows; POS is built from zero-rows."},{"id":"ch2-match-kmap","topic":"ch2-kmap","type":"matching","prompt":"Match each K-map feature with its use.","pairs":[{"left":"Gray-code order","right":"Adjacent labels differ in one bit"},{"left":"Power-of-two group","right":"Eliminates changing variables"},{"left":"Wraparound edge","right":"Allows opposite borders to be adjacent"},{"left":"Don\u0027t-care","right":"Optional cell that may simplify a cover"}],"explanation":"K-map grouping follows Boolean adjacency rather than ordinary binary proximity."},{"id":"ch2-match-blocks","topic":"ch2-mux","type":"matching","prompt":"Match each combinational block or timing term with its function.","pairs":[{"left":"4:1 MUX","right":"Selects one data input using two select bits"},{"left":"2-to-4 decoder","right":"Activates one output for a two-bit input"},{"left":"Propagation delay","right":"Latest time output becomes valid"},{"left":"Contamination delay","right":"Earliest time output may change"}],"explanation":"MUX/decoder roles differ, as do maximum and minimum delay definitions."},{"id":"ch3-storage-02","topic":"ch3-storage","type":"mcq","prompt":"When does a rising-edge D flip-flop capture D?","choices":["At the active rising edge","Whenever D changes","Throughout the entire high clock level","Only when reset is asserted"],"answer":0,"explanation":"An edge-triggered flip-flop samples at its active edge."},{"id":"ch3-storage-03","topic":"ch3-storage","type":"tf","prompt":"A transparent-high D latch can follow changes at D while its enable is high.","choices":["True","False"],"answer":0,"explanation":"A level-sensitive latch is transparent while enabled and holds when disabled."},{"id":"ch3-fsm-02","topic":"ch3-fsm","type":"mcq","prompt":"A state-transition table describes the next state as a function ofâ€¦","choices":["current state and current input","output voltage thresholds only","future clock periods","the instruction cache index"],"answer":0,"explanation":"Next-state logic implements the transition function of present state and inputs."},{"id":"ch3-fsm-03","topic":"ch3-fsm","type":"tf","prompt":"A Moore machine\u0027s output is associated with its current state.","choices":["True","False"],"answer":0,"explanation":"Moore outputs depend only on state; Mealy outputs additionally depend on input."},{"id":"ch3-timing-02","topic":"ch3-timing","type":"mcq","prompt":"Which timing check is governed by the shortest combinational path?","choices":["Hold-time check","Setup-time check","Maximum clock frequency only","Instruction CPI"],"answer":0,"explanation":"Hold uses minimum contamination delay; setup uses maximum propagation delay."},{"id":"ch3-timing-03","topic":"ch3-timing","type":"tf","prompt":"Pipelining can improve steady-state throughput without reducing an individual operation\u0027s total latency.","choices":["True","False"],"answer":0,"explanation":"Overlapping stages can increase completed operations per unit time while each item still traverses all stages."},{"id":"ch3-match-storage","topic":"ch3-storage","type":"matching","prompt":"Match each storage component to its timing behavior.","pairs":[{"left":"D latch","right":"Level-sensitive while enabled"},{"left":"D flip-flop","right":"Samples at an active clock edge"},{"left":"Register","right":"Group of state bits storing a word"},{"left":"Hold behavior","right":"Retains prior value when not updating"}],"explanation":"Latches respond to an enable level; edge-triggered flip-flops update at a clock edge."},{"id":"ch3-match-fsm","topic":"ch3-fsm","type":"matching","prompt":"Match each finite-state-machine term with its meaning.","pairs":[{"left":"Moore output","right":"Function of current state"},{"left":"Mealy output","right":"Function of current state and input"},{"left":"Next-state logic","right":"Computes state transition from state and input"},{"left":"State register","right":"Stores the current encoded state"}],"explanation":"An FSM combines state storage, next-state logic, and output logic."},{"id":"ch3-match-timing","topic":"ch3-timing","type":"matching","prompt":"Match each timing constraint or performance term with its definition.","pairs":[{"left":"Setup time","right":"Input stable before active edge"},{"left":"Hold time","right":"Input stable after active edge"},{"left":"Latency","right":"Time for one item to traverse the system"},{"left":"Throughput","right":"Completed items per unit time"}],"explanation":"Setup and hold bound input stability around a clock edge; latency and throughput measure different performance properties."},{"id":"ch4-comb-extra-01","topic":"ch4-combinational-hdl","type":"mcq","prompt":"Which coding pattern is most likely to infer a latch in a combinational process?","choices":["Assigning the output in every branch","Leaving an output unchanged in one branch","Using a complete case statement with a default","Assigning a Boolean expression unconditionally"],"answer":1,"explanation":"An unassigned path must retain the old value, requiring storage such as a latch."},{"id":"ch4-comb-extra-02","topic":"ch4-combinational-hdl","type":"tf","prompt":"A sensitivity list for combinational behavior must account for every signal read by the logic in older Verilog styles.","choices":["True","False"],"answer":0,"explanation":"If a read signal is omitted in a manually written sensitivity list, simulation may not reevaluate when hardware inputs change."},{"id":"ch4-seq-extra-01","topic":"ch4-sequential-hdl","type":"mcq","prompt":"Why are nonblocking assignments commonly used for clocked register updates?","choices":["They model simultaneous edge-triggered updates","They prevent all hardware from being synthesized","They force combinational behavior","They disable the clock"],"answer":0,"explanation":"Nonblocking updates are scheduled together, avoiding procedural-order artifacts between registers."},{"id":"ch4-seq-extra-02","topic":"ch4-sequential-hdl","type":"tf","prompt":"An incomplete assignment in a combinational HDL process can describe storage rather than purely combinational logic.","choices":["True","False"],"answer":0,"explanation":"A value that must be retained on an unassigned path implies memory behavior."},{"id":"ch4-match","topic":"ch4-combinational-hdl","type":"matching","prompt":"Match each HDL coding pattern with the hardware behavior it describes.","pairs":[{"left":"Complete combinational assignments","right":"Combinational logic without inferred storage"},{"left":"Incomplete combinational assignment","right":"May infer a latch"},{"left":"Clock-edge process","right":"Sequential state update"},{"left":"Nonblocking assignment","right":"Scheduled simultaneous register update"}],"explanation":"Coding style must express whether values are combinational or clocked state."},{"id":"ch5-alu-extra-01","topic":"ch5-alu","type":"mcq","prompt":"For a full adder, carry-out is 1 whenâ€¦","choices":["at least two of A, B, and Cin are 1","all inputs are 0","A differs from B","the sum bit is 1 only"],"answer":0,"explanation":"Cout is the majority function AB+ACin+BCin."},{"id":"ch5-alu-extra-02","topic":"ch5-alu","type":"tf","prompt":"A ripple-carry adder\u0027s worst-case carry delay can grow with the number of bit positions.","choices":["True","False"],"answer":0,"explanation":"Each stage may wait for the preceding carry to propagate."},{"id":"ch5-float-02","topic":"ch5-float","type":"mcq","prompt":"What is the exponent bias used by IEEE 754 single precision?","choices":["127","128","255","1023"],"answer":0,"explanation":"Single precision has an 8-bit exponent with bias 127."},{"id":"ch5-float-03","topic":"ch5-float","type":"tf","prompt":"In normalized single-precision IEEE 754 values, the leading significand 1 is stored explicitly in the fraction field.","choices":["True","False"],"answer":1,"explanation":"The leading 1 is implicit for normalized finite values."},{"id":"ch5-arrays-02","topic":"ch5-arrays","type":"mcq","prompt":"A memory has 1,024 words. How many address bits are required to select one word?","choices":["8","10","16","1,024"],"answer":1,"explanation":"1,024=2^10, so ten address bits select a word."},{"id":"ch5-arrays-03","topic":"ch5-arrays","type":"tf","prompt":"A 256Ã—16 memory contains 256 addressable words, each 16 bits wide.","choices":["True","False"],"answer":0,"explanation":"The first dimension is the word count and the second is the bits per word."},{"id":"ch5-match-alu","topic":"ch5-alu","type":"matching","prompt":"Match each adder signal with its Boolean meaning.","pairs":[{"left":"Sum","right":"A XOR B XOR Cin"},{"left":"Carry-out","right":"AB+ACin+BCin"},{"left":"Ripple carry","right":"Each stage\u0027s carry feeds the next stage"},{"left":"Carry lookahead","right":"Computes carries using generate/propagate logic"}],"explanation":"The sum is parity; carry-out is the majority function of the three inputs."},{"id":"ch5-match-float","topic":"ch5-float","type":"matching","prompt":"Match each IEEE 754 single-precision field or encoding with its role.","pairs":[{"left":"Sign","right":"Selects positive or negative sign"},{"left":"Exponent field","right":"Biased power-of-two scale"},{"left":"Fraction field","right":"Stored fraction bits after the implicit leading one"},{"left":"All-one exponent","right":"Inf/NaN encodings depending on fraction"}],"explanation":"Single precision uses 1 sign, 8 exponent, and 23 fraction bits."},{"id":"ch5-match-memory","topic":"ch5-arrays","type":"matching","prompt":"Match each memory-array quantity with its meaning.","pairs":[{"left":"256Ã—16 array","right":"256 words, 16 bits per word"},{"left":"Address width for 256 words","right":"8 bits"},{"left":"Data width","right":"Bits transferred per selected word"},{"left":"Decoder","right":"Selects a word from its address"}],"explanation":"Word count and word width are separate capacity dimensions."},{"id":"ch6-mips-02","topic":"ch6-mips","type":"mcq","prompt":"For `lw $t0, 12($sp)`, the effective address isâ€¦","choices":["contents($sp)+12 bytes","address of $t0+12 words","PC+12 bytes","contents($sp)Ã—12"],"answer":0,"explanation":"The base-register contents plus signed byte displacement form the effective address."},{"id":"ch6-mips-03","topic":"ch6-mips","type":"tf","prompt":"The `sw` instruction transfers a register value to memory; `lw` transfers a memory value to a register.","choices":["True","False"],"answer":0,"explanation":"The load/store direction is encoded in the instruction operation."},{"id":"ch6-endian-02","topic":"ch6-endian","type":"mcq","prompt":"A 32-bit value 0x12345678 is stored big-endian beginning at byte address 100. What byte is at address 100?","choices":["0x12","0x34","0x56","0x78"],"answer":0,"explanation":"Big-endian places the most-significant byte at the lowest address."},{"id":"ch6-endian-03","topic":"ch6-endian","type":"tf","prompt":"Endianness changes the byte order in memory but does not change the numeric value of the register before storage.","choices":["True","False"],"answer":0,"explanation":"It governs byte-to-address mapping for multi-byte values."},{"id":"ch6-encoding-02","topic":"ch6-encoding","type":"mcq","prompt":"What is the width of the immediate field in a classic 32-bit MIPS I-type instruction?","choices":["6 bits","16 bits","26 bits","32 bits"],"answer":1,"explanation":"I-type uses op(6), rs(5), rt(5), and immediate(16)."},{"id":"ch6-encoding-03","topic":"ch6-encoding","type":"tf","prompt":"A J-type instruction encodes a 26-bit target index rather than a 16-bit PC-relative branch displacement.","choices":["True","False"],"answer":0,"explanation":"The classic J format contains a 6-bit opcode and 26-bit index; branches are I-type."},{"id":"ch6-logic-02","topic":"ch6-logic","type":"mcq","prompt":"`andi` zero-extends its immediate in the classic MIPS model, while `addi` sign-extends its immediate.","choices":["True","False","Only when rt is $zero","Only for negative operands"],"answer":0,"explanation":"Logical immediates are zero-extended; arithmetic immediates are sign-extended."},{"id":"ch6-logic-03","topic":"ch6-logic","type":"tf","prompt":"A logical right shift fills vacated high-order positions with zeros.","choices":["True","False"],"answer":0,"explanation":"Arithmetic right shift instead replicates the sign bit in the usual signed interpretation."},{"id":"ch6-control-02","topic":"ch6-control","type":"mcq","prompt":"In a conventional while-loop translation, where is the exit branch placed?","choices":["At the loop test before the body","After the return instruction","Only inside the function prologue","In the data segment"],"answer":0,"explanation":"Evaluate the condition first; branch to the exit when it is false."},{"id":"ch6-control-03","topic":"ch6-control","type":"tf","prompt":"A loop\u0027s back edge transfers control from the body/update to the loop test.","choices":["True","False"],"answer":0,"explanation":"The loop repeats by returning to the condition check."},{"id":"ch6-arrays-02","topic":"ch6-arrays","type":"mcq","prompt":"For 4-byte array elements, the byte offset of A[i] isâ€¦","choices":["i+4","2i","4i","4^i"],"answer":2,"explanation":"Scale the zero-based index by the element size in bytes."},{"id":"ch6-arrays-03","topic":"ch6-arrays","type":"tf","prompt":"For a zero-based array, A[0] is located at the array base address.","choices":["True","False"],"answer":0,"explanation":"Its offset is zero elements from the base."},{"id":"ch6-functions-02","topic":"ch6-functions","type":"mcq","prompt":"Which register is the stack pointer in the standard MIPS convention?","choices":["$sp","$ra","$a0","$v0"],"answer":0,"explanation":"$sp is register 29 and points to the active stack position."},{"id":"ch6-functions-03","topic":"ch6-functions","type":"tf","prompt":"A recursive function may need a distinct saved return address for each active call frame.","choices":["True","False"],"answer":0,"explanation":"Each nested call can overwrite $ra; stack frames preserve each caller\u0027s continuation."},{"id":"ch6-addressing-02","topic":"ch6-addressing","type":"mcq","prompt":"The classic MIPS conditional branch displacement is measured inâ€¦","choices":["words relative to PC+4","bytes from the current PC","register numbers","absolute physical addresses"],"answer":0,"explanation":"The signed immediate is shifted left two and added to PC+4."},{"id":"ch6-addressing-03","topic":"ch6-addressing","type":"tf","prompt":"A MIPS branch immediate\u0027s encoded numeric value is directly the target byte address.","choices":["True","False"],"answer":1,"explanation":"It is a signed word displacement relative to PC+4, not an absolute byte address."},{"id":"ch6-match-registers","topic":"ch6-mips","type":"matching","prompt":"Match each conventional MIPS register name to its role.","pairs":[{"left":"$sp","right":"Stack pointer"},{"left":"$ra","right":"Return address"},{"left":"$a0â€“$a3","right":"Argument registers"},{"left":"$v0â€“$v1","right":"Return-value registers"}],"explanation":"These names follow the standard register convention used in the supplied course materials."},{"id":"ch6-match-endian","topic":"ch6-endian","type":"matching","prompt":"Match each byte order or load instruction with its behavior.","pairs":[{"left":"Big-endian","right":"Most-significant byte at lowest address"},{"left":"Little-endian","right":"Least-significant byte at lowest address"},{"left":"lb","right":"Loads selected byte with sign extension"},{"left":"lbu","right":"Loads selected byte with zero extension"}],"explanation":"Endian order concerns byte-address mapping; lb/lbu differ in extension."},{"id":"ch6-match-encoding","topic":"ch6-encoding","type":"matching","prompt":"Match each MIPS instruction format with its field widths.","pairs":[{"left":"R-type","right":"6/5/5/5/5/6 bits"},{"left":"I-type","right":"6/5/5/16 bits"},{"left":"J-type","right":"6/26 bits"},{"left":"Branch immediate","right":"Signed word offset from PC+4"}],"explanation":"Classic 32-bit MIPS encodings allocate fields differently by instruction format."},{"id":"ch6-match-logic","topic":"ch6-logic","type":"matching","prompt":"Match each MIPS logical/shift instruction with its effect.","pairs":[{"left":"andi","right":"Bitwise AND with zero-extended immediate"},{"left":"ori","right":"Bitwise OR with zero-extended immediate"},{"left":"sll","right":"Logical left shift by shamt"},{"left":"srl","right":"Logical right shift that fills with zeros"}],"explanation":"Logical immediates are zero-extended; logical shifts insert zeros."},{"id":"ch6-match-control","topic":"ch6-control","type":"matching","prompt":"Match each loop component with its typical control-flow role.","pairs":[{"left":"Test","right":"Computes whether loop continues"},{"left":"Exit branch","right":"Transfers to code after the loop when condition fails"},{"left":"Body","right":"Executes the loop\u0027s work"},{"left":"Back edge","right":"Returns control to the test"}],"explanation":"A loop translation preserves test, body, update, and control-flow structure."},{"id":"ch6-match-array","topic":"ch6-arrays","type":"matching","prompt":"Match each array-address quantity with its meaning for 4-byte elements.","pairs":[{"left":"Base(A)","right":"Address of A[0]"},{"left":"iÃ—4","right":"Byte offset for A[i]"},{"left":"Base+offset","right":"Effective address of A[i]"},{"left":"sll index,2","right":"Multiplies index by four"}],"explanation":"Word-array indexing must scale the zero-based index into a byte offset."},{"id":"ch6-match-functions","topic":"ch6-functions","type":"matching","prompt":"Match each MIPS calling-convention element with its use.","pairs":[{"left":"jal","right":"Calls a function and writes a return address"},{"left":"jr $ra","right":"Returns through saved address"},{"left":"Stack frame","right":"Stores saved registers and local data"},{"left":"Callee-saved register","right":"Function preserves the incoming value"}],"explanation":"Calls and nested calls require preserving state according to the convention."},{"id":"ch6-match-addressing","topic":"ch6-addressing","type":"matching","prompt":"Match each addressing concept with its meaning.","pairs":[{"left":"Register operand","right":"Value read from a named register"},{"left":"Base-plus-offset","right":"Effective address from base plus signed byte displacement"},{"left":"PC-relative branch","right":"PC+4 plus scaled signed offset"},{"left":"Stored program","right":"Instructions represented in addressable memory"}],"explanation":"Operand values, effective addresses, and instruction encodings are distinct."},{"id":"ch7-performance-02","topic":"ch7-performance","type":"mcq","prompt":"A processor with lower CPI is not necessarily faster because execution time also depends onâ€¦","choices":["instruction count and clock period","register number alone","cache line color","instruction mnemonic length"],"answer":0,"explanation":"Compare ICÃ—CPIÃ—clock period for the workload."},{"id":"ch7-performance-03","topic":"ch7-performance","type":"tf","prompt":"Clock period is the reciprocal of clock frequency.","choices":["True","False"],"answer":0,"explanation":"T=1/f, with units converted consistently."},{"id":"ch7-datapath-02","topic":"ch7-datapath","type":"mcq","prompt":"For a store word instruction, which memory control signal must be asserted?","choices":["MemWrite","RegWrite","RegDst","MemtoReg"],"answer":0,"explanation":"sw writes register data into data memory; it does not write a general register."},{"id":"ch7-datapath-03","topic":"ch7-datapath","type":"tf","prompt":"For an `lw` in the standard single-cycle datapath, ALUSrc selects the sign-extended immediate for address calculation.","choices":["True","False"],"answer":0,"explanation":"The ALU adds the base register to the byte displacement."},{"id":"ch7-critical-02","topic":"ch7-critical-path","type":"mcq","prompt":"If a simplified load path is 4 ns instruction fetch + 1 ns register read + 3 ns ALU + 4 ns data read + 1 ns register write, its path delay isâ€¦","choices":["13 ns","12 ns","9 ns","4 ns"],"answer":0,"explanation":"Serial path delays add: 4+1+3+4+1=13 ns."},{"id":"ch7-critical-03","topic":"ch7-critical-path","type":"tf","prompt":"A single-cycle design can use a shorter clock for the fast R-type instruction and a longer clock for lw while executing them.","choices":["True","False"],"answer":1,"explanation":"Every instruction uses the same single-cycle period, set by the slowest supported path."},{"id":"ch7-multicycle-02","topic":"ch7-multicycle","type":"mcq","prompt":"For a workload with 25% five-cycle loads and 75% four-cycle ALU instructions, average CPI isâ€¦","choices":["4.25","4.00","4.75","1.25"],"answer":0,"explanation":"Weighted mean = 0.25Ã—5+0.75Ã—4=4.25."},{"id":"ch7-multicycle-03","topic":"ch7-multicycle","type":"tf","prompt":"In a multicycle processor, the instruction class determines how many cycles it needs under the given control sequence.","choices":["True","False"],"answer":0,"explanation":"Different instructions use different subsets of micro-operations and have different CPI."},{"id":"ch7-pipeline-extra-01","topic":"ch7-pipeline","type":"mcq","prompt":"In the basic five-stage MIPS pipeline, which stage performs the register-file read?","choices":["ID","IF","MEM","WB"],"answer":0,"explanation":"ID decodes the instruction and reads source registers."},{"id":"ch7-pipeline-extra-02","topic":"ch7-pipeline","type":"tf","prompt":"Ideal pipelining reduces the latency of every individual instruction to one stage.","choices":["True","False"],"answer":1,"explanation":"An instruction still traverses all stages; overlap improves throughput."},{"id":"ch7-hazards-02","topic":"ch7-hazards","type":"mcq","prompt":"A load-use dependence can still require a stall with forwarding becauseâ€¦","choices":["loaded data becomes available after the next instruction\u0027s EX operand is needed","forwarding disables the ALU","registers cannot be read in ID","loads never write a register"],"answer":0,"explanation":"In the standard five-stage timing model, load data arrives too late for the immediately following EX stage."},{"id":"ch7-hazards-03","topic":"ch7-hazards","type":"tf","prompt":"Forwarding resolves a RAW dependence by routing a produced value directly to a later consumer.","choices":["True","False"],"answer":0,"explanation":"Bypassing avoids waiting for register-file writeback when timing permits."},{"id":"ch7-control-hazards-02","topic":"ch7-control-hazards","type":"mcq","prompt":"When a branch resolves taken after fall-through instructions were fetched, what should happen to wrong-path instructions?","choices":["Flush them","Commit their register writes","Convert them to loads","Write them into the branch target"],"answer":0,"explanation":"Wrong-path younger instructions are squashed and must not commit state."},{"id":"ch7-control-hazards-03","topic":"ch7-control-hazards","type":"tf","prompt":"Every branch instruction is necessarily a branch misprediction.","choices":["True","False"],"answer":1,"explanation":"A branch is mispredicted only when the predicted outcome or target is wrong."},{"id":"ch7-match-performance","topic":"ch7-performance","type":"matching","prompt":"Match each performance term with its definition.","pairs":[{"left":"Instruction count","right":"Number of executed instructions in the workload"},{"left":"CPI","right":"Average clock cycles per instruction"},{"left":"Clock period","right":"Time per clock cycle"},{"left":"CPU time","right":"ICÃ—CPIÃ—clock period"}],"explanation":"Performance comparisons must combine workload instruction count, CPI, and cycle time."},{"id":"ch7-match-datapath","topic":"ch7-datapath","type":"matching","prompt":"Match each single-cycle control signal with its role.","pairs":[{"left":"RegWrite","right":"Enable register-file write"},{"left":"MemWrite","right":"Enable data-memory write"},{"left":"ALUSrc","right":"Select ALU second operand source"},{"left":"MemtoReg","right":"Select register writeback source"}],"explanation":"Control signals select data paths and enable state updates."},{"id":"ch7-match-critical","topic":"ch7-critical-path","type":"matching","prompt":"Match each simplified instruction path with its delay using the stated component timings.","pairs":[{"left":"lw: 4+1+3+4+1 ns","right":"13 ns"},{"left":"sw: 4+1+3+4 ns","right":"12 ns"},{"left":"R-type: 4+1+3+1 ns","right":"9 ns"},{"left":"Single-cycle period","right":"Longest supported instruction path"}],"explanation":"The load path is longest in the stated timing model and therefore sets the clock period."},{"id":"ch7-match-multicycle","topic":"ch7-multicycle","type":"matching","prompt":"Match each workload/performance quantity with its correct interpretation.","pairs":[{"left":"Class fraction","right":"Share of executed instructions in that class"},{"left":"Class cycle count","right":"Cycles that instruction class takes"},{"left":"Average CPI","right":"Sum of fractionÃ—class CPI"},{"left":"Single-cycle CPI","right":"One cycle per instruction"}],"explanation":"Average CPI is a weighted mean across the instruction mix."},{"id":"ch7-match-pipeline","topic":"ch7-pipeline","type":"matching","prompt":"Match each five-stage pipeline stage to its main action.","pairs":[{"left":"IF","right":"Fetch instruction"},{"left":"ID","right":"Decode and read registers"},{"left":"EX","right":"ALU operation/address calculation"},{"left":"MEM","right":"Read or write data memory"},{"left":"WB","right":"Write result to register file"}],"explanation":"The conventional order is IF, ID, EX, MEM, WB."},{"id":"ch7-match-hazard","topic":"ch7-hazards","type":"matching","prompt":"Match each hazard remedy with its effect.","pairs":[{"left":"Forwarding","right":"Bypasses a value to a dependent instruction"},{"left":"Load-use stall","right":"Adds a bubble when load data is not ready"},{"left":"Instruction reordering","right":"Places independent work between dependent operations"},{"left":"RAW dependence","right":"Later read follows an earlier write to the same register"}],"explanation":"A data dependence can be managed by bypass, scheduling, or a timing-required stall."},{"id":"ch7-match-controlhazard","topic":"ch7-control-hazards","type":"matching","prompt":"Match each branch term with its meaning.","pairs":[{"left":"Branch prediction","right":"Guesses the next control-flow outcome"},{"left":"Misprediction","right":"Prediction disagrees with resolved outcome"},{"left":"Flush","right":"Squash younger wrong-path instructions"},{"left":"Branch penalty","right":"Wasted cycles associated with a misprediction"}],"explanation":"Only wrong-path instructions are discarded, and penalty depends on resolution timing."},{"id":"ch8-cache-03","topic":"ch8-cache","type":"mcq","prompt":"A direct-mapped cache has 64 lines and a 16-byte block. For byte addresses, how many low address bits are the block offset?","choices":["4","6","10","16"],"answer":0,"explanation":"A 16-byte block requires log2(16)=4 offset bits."},{"id":"ch8-cache-04","topic":"ch8-cache","type":"tf","prompt":"In a direct-mapped cache, each memory block can map to exactly one cache line.","choices":["True","False"],"answer":0,"explanation":"The index determines one line; the tag checks which memory block occupies it."},{"id":"ch8-virtual-memory-02","topic":"ch8-virtual-memory","type":"mcq","prompt":"With 4 KiB pages, how many bits are in the page offset for byte addresses?","choices":["10","12","4,096","20"],"answer":1,"explanation":"4 KiB=2^12 bytes, so the offset is 12 bits."},{"id":"ch8-virtual-memory-03","topic":"ch8-virtual-memory","type":"tf","prompt":"Address translation changes the page/frame number while preserving the byte offset within the page.","choices":["True","False"],"answer":0,"explanation":"The offset identifies the same byte position in the translated physical frame."},{"id":"ch8-io-02","topic":"ch8-io","type":"mcq","prompt":"In memory-mapped I/O, device registers are accessed throughâ€¦","choices":["addresses in the processor\u0027s memory address space","only CPU condition flags","a second instruction set with no addresses","cache tags only"],"answer":0,"explanation":"Loads and stores to assigned addresses communicate with device registers."},{"id":"ch8-io-03","topic":"ch8-io","type":"tf","prompt":"An I/O-mapped register\u0027s address can be used with ordinary load/store operations in a memory-mapped design.","choices":["True","False"],"answer":0,"explanation":"Memory-mapped devices share the address space and load/store access mechanism."},{"id":"ch8-match-cache","topic":"ch8-cache","type":"matching","prompt":"Match each cache quantity with its role.","pairs":[{"left":"Block offset","right":"Selects a byte within a block"},{"left":"Index","right":"Selects a cache set/line"},{"left":"Tag","right":"Identifies which memory block is stored"},{"left":"AMAT","right":"Hit time + miss rateÃ—miss penalty"}],"explanation":"Address fields locate a cache position and verify its contents; AMAT combines hit and miss costs."},{"id":"ch8-match-vm","topic":"ch8-virtual-memory","type":"matching","prompt":"Match each virtual-memory quantity with its meaning.","pairs":[{"left":"VPN","right":"Virtual page number"},{"left":"Page offset","right":"Byte position within a page"},{"left":"Page table","right":"Maps a virtual page to a physical frame"},{"left":"TLB","right":"Caches recent address translations"}],"explanation":"Translation changes page identity while preserving the offset."},{"id":"ch8-match-io","topic":"ch8-io","type":"matching","prompt":"Match each I/O term with its role.","pairs":[{"left":"Memory-mapped I/O","right":"Device registers share the memory address space"},{"left":"Device register","right":"Addressable control/status/data location"},{"left":"Load/store access","right":"Transfers values between CPU and mapped device"},{"left":"Polling","right":"CPU repeatedly checks a device status condition"}],"explanation":"Memory-mapped I/O uses ordinary address and load/store mechanisms for device registers."}]};